const cfg = $input.first().json;
const tz = String(cfg.timezone || 'Europe/Berlin');
const base = String(cfg.officialBaseUrl || '').replace(/\/$/, '');
const manualRaw = String(cfg.manualDrawDate || '').trim();
const now = new Date();
const fetchedAt = now.toISOString();
const WEEKDAY = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };

function berlinParts(date) {
  const dtf = new Intl.DateTimeFormat('en-GB', {
    timeZone: tz,
    weekday: 'short',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hourCycle: 'h23',
  });
  const out = {};
  for (const part of dtf.formatToParts(date)) {
    if (part.type !== 'literal') out[part.type] = part.value;
  }
  return {
    weekday: WEEKDAY[out.weekday],
    year: Number(out.year),
    month: Number(out.month),
    day: Number(out.day),
    hour: Number(out.hour),
    minute: Number(out.minute),
    ymd: `${out.year}-${out.month}-${out.day}`,
  };
}

function addDays(ymd, days) {
  const [y, m, d] = ymd.split('-').map(Number);
  const dt = new Date(Date.UTC(y, m - 1, d + days));
  return `${dt.getUTCFullYear()}-${String(dt.getUTCMonth() + 1).padStart(2, '0')}-${String(dt.getUTCDate()).padStart(2, '0')}`;
}

function isIsoDate(value) {
  return /^\d{4}-\d{2}-\d{2}$/.test(value);
}

function isSundayYmd(ymd) {
  if (!isIsoDate(ymd)) return false;
  const [y, m, d] = ymd.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d, 12, 0, 0)).getUTCDay() === 0;
}

const berlin = berlinParts(now);
let requestedDrawDate;
let manualBackfill = false;
let selectionError = null;

if (manualRaw) {
  manualBackfill = true;
  requestedDrawDate = manualRaw;
  if (!isIsoDate(manualRaw) || !isSundayYmd(manualRaw)) {
    selectionError = 'invalid_manual_draw_date';
  } else if (manualRaw > berlin.ymd) {
    selectionError = 'future_date_blocked';
  }
} else if (berlin.weekday === 0) {
  requestedDrawDate = berlin.hour < 17 ? addDays(berlin.ymd, -7) : berlin.ymd;
} else {
  requestedDrawDate = addDays(berlin.ymd, -berlin.weekday);
}

if (!selectionError && requestedDrawDate > berlin.ymd) {
  selectionError = 'future_date_blocked';
}

return [{
  json: {
    ...cfg,
    requestedDrawDate,
    officialUrl: `${base}/${requestedDrawDate}`,
    manualBackfill,
    fetchedAt,
    berlinNow: berlin.ymd,
    berlinHour: berlin.hour,
    selectionError,
  },
}];

const select = $('Select Official Draw Date').first().json;
const cfg = $('Import Configuration').first().json;
const http = $input.first().json;
const tz = String(select.timezone || 'Europe/Berlin');
const WEEKDAY = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
const statusCode = Number(http.statusCode ?? http.status ?? 0);
let body = http.body !== undefined ? http.body : http;
const validation = {
  officialStatusCode: statusCode,
  jackpotSource: null,
  drawValid: false,
  drawFailReason: null,
  numberCount: 0,
};

function isObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function positiveJackpot(value) {
  if (value === null || value === undefined) return null;
  if (typeof value === 'string' && value.trim() === '') return null;
  const n = typeof value === 'number' ? value : Number(value);
  if (!Number.isFinite(n) || n <= 0) return null;
  return n;
}

function berlinParts(date) {
  const dtf = new Intl.DateTimeFormat('en-GB', {
    timeZone: tz,
    weekday: 'short',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hourCycle: 'h23',
  });
  const out = {};
  for (const part of dtf.formatToParts(date)) {
    if (part.type !== 'literal') out[part.type] = part.value;
  }
  return {
    weekday: WEEKDAY[out.weekday],
    year: Number(out.year),
    month: Number(out.month),
    day: Number(out.day),
    hour: Number(out.hour),
    minute: Number(out.minute),
    ymd: `${out.year}-${out.month}-${out.day}`,
  };
}

function addDays(ymd, days) {
  const [y, m, d] = ymd.split('-').map(Number);
  const dt = new Date(Date.UTC(y, m - 1, d + days));
  return `${dt.getUTCFullYear()}-${String(dt.getUTCMonth() + 1).padStart(2, '0')}-${String(dt.getUTCDate()).padStart(2, '0')}`;
}

function berlinWallClockToUtcDate(ymd, hour, minute) {
  const [year, month, day] = ymd.split('-').map(Number);
  let guess = Date.UTC(year, month - 1, day, hour, minute, 0);
  for (let i = 0; i < 12; i++) {
    const p = berlinParts(new Date(guess));
    const got = Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute);
    const want = Date.UTC(year, month - 1, day, hour, minute);
    const delta = want - got;
    if (
      delta === 0 &&
      p.year === year &&
      p.month === month &&
      p.day === day &&
      p.hour === hour &&
      p.minute === minute
    ) {
      return new Date(guess);
    }
    guess += delta;
  }
  return new Date(guess);
}

let reason = null;
if (select.selectionError) {
  reason = select.selectionError;
} else if (statusCode === 404) {
  reason = 'official_draw_not_available';
} else if (!statusCode) {
  reason = 'official_transport_failure';
} else if (statusCode < 200 || statusCode >= 300) {
  reason = 'official_source_unavailable';
} else if (typeof body === 'string') {
  const trimmed = body.trim();
  if (trimmed.startsWith('<') || (!trimmed.startsWith('{') && !trimmed.startsWith('['))) {
    reason = 'official_response_not_json';
  } else {
    try {
      body = JSON.parse(trimmed);
    } catch (error) {
      reason = 'official_response_not_json';
    }
  }
}

const bingo = !reason && isObject(body) ? body.bingo : null;
if (!reason && !isObject(bingo)) {
  reason = 'official_response_malformed';
}

const updateStatus = !select.manualBackfill || cfg.updateStatusDuringBackfill === true;
let jackpot = null;
let nextDrawAt = null;
let draw = null;

if (!reason && updateStatus) {
  const fromNew = positiveJackpot(bingo.jackpotNew);
  const fromCurrent = positiveJackpot(bingo.jackpotCurrently);
  if (fromNew != null) {
    jackpot = fromNew;
    validation.jackpotSource = 'jackpotNew';
  } else if (fromCurrent != null) {
    jackpot = fromCurrent;
    validation.jackpotSource = 'jackpotCurrently';
  }
}

if (!reason && updateStatus) {
  const nowParts = berlinParts(new Date());
  let nextYmd;
  if (nowParts.weekday === 0 && nowParts.hour < 17) nextYmd = nowParts.ymd;
  else if (nowParts.weekday === 0) nextYmd = addDays(nowParts.ymd, 7);
  else nextYmd = addDays(nowParts.ymd, 7 - nowParts.weekday);
  nextDrawAt = berlinWallClockToUtcDate(nextYmd, 17, 0).toISOString();
}

if (!reason) {
  const drawMs = Number(bingo.drawDate);
  if (!Number.isFinite(drawMs) || drawMs <= 0) {
    validation.drawFailReason = 'invalid_draw_date';
  } else {
    const drawBerlin = berlinParts(new Date(drawMs));
    if (drawBerlin.weekday !== 0) {
      validation.drawFailReason = 'draw_date_not_sunday';
    } else {
      const collection = Array.isArray(bingo.drawNumbersCollection)
        ? bingo.drawNumbersCollection.slice()
        : [];
      collection.sort((a, b) => Number(a && a.drawIndex) - Number(b && b.drawIndex));
      const numbers = [];
      let invalid = false;
      for (const item of collection) {
        const n = Number(item && item.drawNumber);
        if (!Number.isInteger(n) || n < 1 || n > 75) {
          invalid = true;
          break;
        }
        numbers.push(n);
      }
      validation.numberCount = numbers.length;
      if (invalid) validation.drawFailReason = 'number_out_of_range_or_not_integer';
      else if (numbers.length !== 22) validation.drawFailReason = 'incorrect_number_count';
      else if (new Set(numbers).size !== 22) validation.drawFailReason = 'duplicate_draw_number';
      else {
        validation.drawValid = true;
        let sourceUpdatedAt = select.fetchedAt;
        const lastMs = Number(bingo.lastDataChange);
        if (Number.isFinite(lastMs) && lastMs > 0) {
          sourceUpdatedAt = new Date(lastMs).toISOString();
        }
        draw = {
          draw_date: drawBerlin.ymd,
          winning_numbers: numbers,
          source_updated_at: sourceUpdatedAt,
          fetched_at: select.fetchedAt,
        };
      }
    }
  }
}

const importBody = {};
if (!reason) {
  if (jackpot != null) importBody.current_jackpot_eur = jackpot;
  if (nextDrawAt) importBody.next_draw_at = nextDrawAt;
  if (draw) importBody.draw = draw;
  if (jackpot == null && !nextDrawAt && !draw) {
    reason = 'no_safe_importable_data';
  }
}

let route = 'no_op';
if (!reason) {
  route = cfg.dryRun === true ? 'dry_run' : 'import';
}

return [{
  json: {
    route,
    reason,
    requestedDrawDate: select.requestedDrawDate,
    manualBackfill: select.manualBackfill,
    dryRun: cfg.dryRun === true,
    importBody: reason ? null : importBody,
    validation,
    fetchedAt: select.fetchedAt,
  },
}];

const incoming = $input.first().json;
const normalized = $('Normalize and Validate Bingo').first().json;

if (incoming.dryRun === true || incoming.route === 'dry_run' || normalized.dryRun === true && incoming.statusCode == null) {
  return [{
    json: {
      status: 'imported',
      dryRun: true,
      requestedDrawDate: normalized.requestedDrawDate,
      payload: normalized.importBody,
      validation: normalized.validation,
    },
  }];
}

const statusCode = Number(incoming.statusCode ?? incoming.status ?? 0);
const body = normalized.importBody || {};
return [{
  json: {
    status: 'imported',
    requested_draw_date: normalized.requestedDrawDate,
    jackpot_imported: body.current_jackpot_eur != null,
    draw_imported: Boolean(body.draw),
    winning_number_count: body.draw && Array.isArray(body.draw.winning_numbers)
      ? body.draw.winning_numbers.length
      : 0,
    target_status_code: statusCode,
  },
}];

const normalized = $input.first().json;
return [{
  json: {
    status: 'no_op',
    requested_draw_date: normalized.requestedDrawDate || null,
    reason: normalized.reason || 'no_safe_importable_data',
  },
}];

const http = $input.first().json;
const statusCode = Number(http.statusCode ?? http.status ?? 0);
const body = http.body;
let message = 'BingoBlogs import failed.';
if (statusCode === 401) message = 'Import credential was rejected.';
else if (statusCode === 422) message = 'Normalized payload was rejected.';
else if (statusCode >= 500) message = 'BingoBlogs server failure.';
else if (typeof body === 'string' && body.trim().startsWith('<')) message = 'Invalid BingoBlogs response.';
else if (!statusCode) message = 'Import request timed out.';
return [{
  json: {
    status: 'failed',
    stage: 'bingo_blogs_import',
    status_code: statusCode,
    message,
  },
}];
